-- ONE MORE DRAFT LISTING requested 27 November 2026. All hidden until checked and published in admin.
-- Skipped if a listing with the same name or slug already exists.

insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'before-you-bet', 'Before You Bet', array['tipster','news']::listing_type[], 'Free Australian betting previews, tips and industry news across racing and sport.', 'A long-running Australian betting site publishing free match previews and best bets for AFL, NRL, racing, cricket, the A-League and US sports, alongside betting industry news. Racing tips for the main Saturday meetings go up each week.', 'https://www.beforeyoubet.com.au', 'free'::pricing_model, null, array['afl','nrl','racing','cricket','soccer','nba']::text[], null, array['Free picks','Write-ups with reasoning','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "DECISION NEEDED: sites like this usually earn from bookmaker reviews, sign-up offers and affiliate links. Open the site and check how much bookmaker promotion it carries before publishing, given your no-bookmaker stance and the Australian rules starting 1 January 2027. Established account (8,400 followers, on X since 2013). Confirm the web address and the sports to tick.", "country": "AU"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Before You Bet')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://www.beforeyoubet.com.au'),('X','https://x.com/Before_You_Bet'),('Linktree','https://linktr.ee/beforeyoubet')) as v(platform,url) where l.slug = 'before-you-bet' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
